    def receive_message(self, message: Info) -> Info:
        # Extract input data
        current_grid = message.message[0].data[0]  # List of lists representing the grid
        current_hint = message.message[0].data[1]  # String describing the hint
        player_idx = message.message[0].data[2]  # Integer, 1 or 2, indicating the player

        # Define helper functions
        def parse_hint(hint_str):
            words = hint_str.split()
            op = words[0]
            cond_str = ' '.join(words[1:])
            cond_words = cond_str.split()
            if cond_str.startswith("is less than"):
                condition = 'less than'
                v1 = int(cond_words[-1])
            elif cond_str.startswith("is greater than"):
                condition = 'greater than'
                v1 = int(cond_words[-1])
            elif cond_str == "is even":
                condition = 'even'
                v1 = None
            elif cond_str == "is odd":
                condition = 'odd'
                v1 = None
            elif cond_str.startswith("is between"):
                condition = 'between inclusive'
                v1 = int(cond_words[2])
                v2_str = cond_words[4].rstrip(',').rstrip()
                v2 = int(v2_str)
            elif cond_str.startswith("contains digit"):
                condition = 'contains digit'
                v1 = int(cond_words[-1])
            else:
                raise ValueError(f"Unknown condition: {cond_str}")
            return op, condition, v1, v2

        def satisfies_hint(row_1based, col_1based, op, condition, v1, v2):
            if op == 'sum':
                val = row_1based + col_1based
            elif op == 'product':
                val = row_1based * col_1based
            elif op == 'difference':
                val = abs(row_1based - col_1based)
            else:
                raise ValueError(f"Unknown operation: {op}")
            if condition == 'less than':
                return val < v1
            elif condition == 'greater than':
                return val > v1
            elif condition == 'contains digit':
                val_str = str(val)
                digit_str = str(v1)
                return digit_str in val_str
            elif condition == 'even':
                return val % 2 == 0
            elif condition == 'odd':
                return val % 2 == 1
            elif condition == 'between inclusive':
                return v1 <= val <= v2
            else:
                raise ValueError(f"Unknown condition: {condition}")

        def has_path(grid_copy, p_val, is_row_wise):
            rows_g = len(grid_copy)
            if rows_g == 0:
                return False
            cols_g = len(grid_copy[0])
            if not is_row_wise:  # Left to right
                start_cells = [(r, 0) for r in range(rows_g) if grid_copy[r][0] == p_val]
                target_check = lambda r, c: c == cols_g - 1
            else:  # Top to bottom
                start_cells = [(0, c) for c in range(cols_g) if grid_copy[0][c] == p_val]
