                    max_reach = max(reach for _, reach in reaches)
                    best_positions = [pos for pos, reach in reaches if reach == max_reach]
                    best_positions.sort()  # Sort by row, then col
                    selected_pos = best_positions[0]
                else:
                    # No component, prefer start side: min col for P1, min row for P2
                    if player_idx == 1:
                        sorted_allowable = sorted(allowable_positions, key=lambda x: (x[1], x[0]))  # Sort by col, then row
                        selected_pos = sorted_allowable[0]
                    else:  # player_idx == 2
                        sorted_allowable = sorted(allowable_positions, key=lambda x: (x[0], x[1]))  # Sort by row, then col
                        selected_pos = sorted_allowable[0]

            # Convert from 0-based to 1-based for output
            position_selected = (selected_pos[0] + 1, selected_pos[1] + 1)

