        condition_str = words[1]
        if condition_str.startswith("is less than"):
            v1 = int(condition_str[len("is less than"):].strip())
            return operation, "less than", v1, None
        elif condition_str.startswith("is greater than"):
            v1 = int(condition_str[len("is greater than"):].strip())
            return operation, "greater than", v1, None
        elif condition_str.startswith("contains digit"):
            v1 = int(condition_str[len("contains digit"):].strip())
            return operation, "contains digit", v1, None
        elif condition_str == "is even":
            return operation, "even", None, None
        elif condition_str == "is odd":
            return operation, "odd", None, None
        elif condition_str.startswith("is between"):
            cleaned = condition_str.replace("is between", "").replace("inclusive", "").replace(",", "").strip()
            num_parts = [part.strip() for part in cleaned.split("and")]
            if len(num_parts) != 2:
                raise ValueError("Invalid between condition")
            v1 = int(num_parts[0])
            v2 = int(num_parts[1])
