import collections  # for queue in BFS

class SuperplyCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        # Extract inputs from message
        current_grid = message.message[0].data[0]  # list of lists, 0-indexed in code but positions 1-indexed in game
        current_hint = message.message[0].data[1]  # string, e.g., "sum is less than 10"
        player_idx = message.message[0].data[2]  # integer, 1 or 2

        # Parse the hint to get operation, condition type, and parameters
        operation, condition_type, params = self.parse_hint(current_hint)

        # Get all legal moves in 0-indexed coordinates
        legal_moves = self.get_legal_moves(current_grid, operation, condition_type, params)  # list of (r_idx, c_idx) 0-indexed

        N = len(current_grid)  # Assume square grid, get size

        position_selected_0 = None  # Will store 0-indexed position

        if not legal_moves:
            # No legal moves, return an arbitrary position, e.g., (0,0) 0-indexed, which is (1,1) 1-indexed
            position_selected_0 = (0, 0)
        else:
            # Check for winning moves
            winning_moves = [move for move in legal_moves if self.is_player_connected(current_grid, player_idx, additional_pos=move)]
            if winning_moves:
                # Choose the first winning move after sorting for determinism
                winning_moves.sort()  # Sort by row then column
                position_selected_0 = winning_moves[0]
            else:
                # No winning move, get my connected component to start boundary
                my_component = self.get_connected_component_to_start(current_grid, player_idx)  # set of (r_idx, c_idx) 0-indexed

                # Find adjacent positions to my component in 0-indexed
                adj_set = set()
                for pos in my_component:
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr != 0 or dc != 0:
                                nr = pos[0] + dr
                                nc = pos[1] + dc
                                if 0 <= nr < N and 0 <= nc < N:
                                    adj_set.add((nr, nc))  # Add all adjacent cells, regardless of occupation

                # Find legal moves that are adjacent to the component
                legal_adj_moves = [move for move in legal_moves if move in adj_set]

                if legal_adj_moves:
                    # Choose the move that maximizes the coordinate towards the goal
                    if player_idx == 1:  # Player 1: maximize column (c_idx)
                        position_selected_0 = max(legal_adj_moves, key=lambda x: x[1])
                    elif player_idx == 2:  # Player 2: maximize row (r_idx)
                        position_selected_0 = max(legal_adj_moves, key=lambda x: x[0])
                else:
                    # No adjacent legal moves
                    if not my_component:  # No component, play near start boundary
                        if player_idx == 1:  # Minimize column for Player 1
                            position_selected_0 = min(legal_moves, key=lambda x: x[1])
                        elif player_idx == 2:  # Minimize row for Player 2
                            position_selected_0 = min(legal_moves, key=lambda x: x[0])
                    else:  # Component exists, play towards goal
                        if player_idx == 1:  # Maximize column for Player 1
                            position_selected_0 = max(legal_moves, key=lambda x: x[1])
                        elif player_idx == 2:  # Maximize row for Player 2
                            position_selected_0 = max(legal_moves, key=lambda x: x[0])

        # Convert the selected position to 1-indexed
        position_selected = (position_selected_0[0] + 1, position_selected_0[1] + 1)

        # Return the Info message with the selected position
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=position_selected, type='custom')]
        )

    # Helper method to parse the hint
    def parse_hint(self, hint_str: str):
        parts = hint_str.split()
        operation = parts[0]
        condition_part = ' '.join(parts[1:])

        if condition_part.startswith("is less than"):
            v1_str = condition_part[len("is less than "):].strip()
            v1 = int(v1_str)
            condition_type = "less_than"
            params = {"v1": v1}
        elif condition_part.startswith("is greater than"):
            v1_str = condition_part[len("is greater than "):].strip()
            v1 = int(v1_str)
            condition_type = "greater_than"
            params = {"v1": v1}
        elif condition_part.startswith("contains digit"):
            v1_str = condition_part[len("contains digit "):].strip()
            v1 = v1_str  # Keep as string for digit check
            condition_type = "contains_digit"
            params = {"v1": v1}
        elif condition_part == "is even":
            condition_type = "even"
            params = {}
        elif condition_part == "is odd":
            condition_type = "odd"
            params = {}
        elif condition_part.startswith("is between"):
            # Remove "is between " and ", inclusive" and split by " and "
            cleaned = condition_part.replace("is between ", "").replace(", inclusive", "").strip()
            v1_str, v2_str = cleaned.split(" and ")
            v1 = int(v1_str)
            v2 = int(v2_str)
            condition_type = "between"
            params = {"v1": v1, "v2": v2}
        else:
            raise ValueError(f"Invalid hint: {hint_str}")

        return operation, condition_type, params

    # Helper method to check if a position satisfies the hint
    def satisfies_hint(self, row: int, col: int, operation: str, condition_type: str, params: dict):  # row and col are 1-indexed
        if operation == "sum":
            value = row + col
        elif operation == "product":
            value = row * col
        elif operation == "difference":
            value = abs(row - col)  # Assume absolute difference
        else:
            raise ValueError("Invalid operation")

        if condition_type == "less_than":
            return value < params["v1"]
        elif condition_type == "greater_than":
            return value > params["v1"]
        elif condition_type == "contains_digit":
            value_str = str(value)
            digit_str = params["v1"]
            return digit_str in value_str
        elif condition_type == "even":
            return value % 2 == 0
        elif condition_type == "odd":
            return value % 2 != 0
        elif condition_type == "between":
            return params["v1"] <= value <= params["v2"]
        else:
            raise ValueError("Invalid condition type")

    # Helper method to get legal moves in 0-indexed coordinates
    def get_legal_moves(self, grid: List[List[int]], operation: str, condition_type: str, params: dict):
        N = len(grid)
        legal = []
        for r_idx in range(N):
            for c_idx in range(N):
                # Convert to 1-indexed for hint check
                if grid[r_idx][c_idx] == 0 and self.satisfies_hint(r_idx + 1, c_idx + 1, operation, condition_type, params):
                    legal.append((r_idx, c_idx))  # Store 0-indexed
        return legal

    # Helper method to get the set of cells belonging to a player, with optional additional position
    def get_player_cells(self, grid: List[List[int]], player: int, additional_pos: tuple = None):
        cell_set = set()
        N = len(grid)
        for i in range(N):
            for j in range(N):
                if grid[i][j] == player:
                    cell_set.add((i, j))
        if additional_pos:
            cell_set.add(additional_pos)  # Add additional position as if it belongs to player
        return cell_set

    # Helper method to check if player is connected after hypothetical move
    def is_player_connected(self, grid: List[List[int]], player: int, additional_pos: tuple = None):
        N = len(grid)
        player_cells = self.get_player_cells(grid, player, additional_pos)

        if player == 1:  # Connect left (c_idx=0) to right (c_idx=N-1)
