            elif 'is between' in condition_part:
                cond_words = condition_part.split()
                idx_between = cond_words.index('between')
                idx_and = cond_words.index('and')
                v1_str = cond_words[idx_between + 1].rstrip(',')
                v2_str = cond_words[idx_and + 1].rstrip(',')
                v1 = int(v1_str)
                v2 = int(v2_str)
