        elif cond_first == 'contains' and len(cond_words) > 1 and cond_words[1] == 'digit':
            v1 = cond_words[2]  # string digit
            def cond_pred(val):
                return str(v1) in str(val)
        else:
            raise ValueError("Unknown condition")
        def predicate(row, col):
            if op == 'sum':
                val = row + col
            elif op == 'product':
                val = row * col
